// Build the business row, niche-default services, two links and a 4-digit PIN.
// Defensive: PostgREST returns [{...}]; some n8n versions unwrap it to an object.
let p = $('Get Prospect').item.json;
if (Array.isArray(p)) p = p[0] || {};

const slug = p.slug;
const niche = (p.niche || '').toLowerCase();
const businessName = p.business_name || slug;
const ownerFirst = (p.owner_first_name || (p.raw_data && p.raw_data.owner_first_name) || '').trim();
const pin = String(Math.floor(1000 + Math.random() * 9000));
const bookingUrl = 'https://booking-page-beta.vercel.app/?biz=' + slug;
const adminUrl = 'https://booking-page-beta.vercel.app/admin?biz=' + slug;

const SERVICE_SETS = {
  lash: [
    { name: 'Classic Full Set', duration: 120, price: 'R450' },
    { name: 'Hybrid Full Set', duration: 135, price: 'R550' },
    { name: 'Volume Full Set', duration: 150, price: 'R650' },
    { name: 'Lash Fill', duration: 60, price: 'R280' },
    { name: 'Lash Removal', duration: 30, price: 'R150' }
  ],
  nail: [
    { name: 'Gel Manicure', duration: 60, price: 'R280' },
    { name: 'Gel Overlay', duration: 75, price: 'R350' },
    { name: 'Acrylic Full Set', duration: 105, price: 'R450' },
    { name: 'Soak Off & Refresh', duration: 45, price: 'R200' },
    { name: 'Pedicure', duration: 60, price: 'R320' }
  ],
  hair: [
    { name: 'Cut & Blow Wave', duration: 60, price: 'R350' },
    { name: 'Full Colour', duration: 150, price: 'R900' },
    { name: 'Highlights', duration: 180, price: 'R1200' },
    { name: 'Treatment', duration: 45, price: 'R300' },
    { name: 'Blow Wave', duration: 45, price: 'R250' }
  ],
  brow: [
    { name: 'Brow Shape & Tint', duration: 45, price: 'R250' },
    { name: 'Brow Lamination', duration: 60, price: 'R450' },
    { name: 'Lash Lift', duration: 60, price: 'R450' },
    { name: 'Henna Brows', duration: 50, price: 'R320' },
    { name: 'Microblading', duration: 120, price: 'R1500' }
  ],
  default: [
    { name: 'Consultation', duration: 30, price: 'R150' },
    { name: 'Signature Treatment', duration: 60, price: 'R450' },
    { name: 'Express Service', duration: 30, price: 'R250' },
    { name: 'Premium Package', duration: 120, price: 'R850' }
  ]
};
const ACCENTS = { lash: '#B76E79', nail: '#C084FC', hair: '#0EA5E9', brow: '#A16207', default: '#7B3FE4' };

let key = 'default';
if (niche.includes('lash')) key = 'lash';
else if (niche.includes('nail')) key = 'nail';
else if (niche.includes('hair')) key = 'hair';
else if (niche.includes('brow')) key = 'brow';

const accent = ACCENTS[key];
const services = SERVICE_SETS[key].map((s, i) => ({ business_id: slug, name: s.name, duration: s.duration, price: s.price, sort_order: i }));

const business = {
  id: slug,
  name: businessName,
  slug: slug,
  accent_color: accent,
  prospect_id: p.id,
  is_streamline_owned: true,
  show_streamline_promo: true,
  working_days: [1, 2, 3, 4, 5, 6],
  working_hours: { start: 8, end: 17 },
  slot_interval: 30,
  advance_days: 30,
  same_day: true,
  phone: p.whatsapp_e164 || p.phone_e164 || null
};

return [{ json: {
  prospect_id: p.id,
  slug,
  niche: p.niche || key,
  business_name: businessName,
  owner_first_name: ownerFirst,
  pin,
  booking_url: bookingUrl,
  admin_url: adminUrl,
  business,
  services
} }];

